package com.justeam.rdp.dataset;

import com.justeam.rdp.audit.AuditService;
import com.justeam.rdp.common.BusinessException;
import com.justeam.rdp.common.JsonSupport;
import com.justeam.rdp.security.CurrentUser;
import com.justeam.rdp.security.RdpProperties;
import com.justeam.rdp.security.SecondaryCredentialService;
import com.justeam.rdp.security.UserPrincipal;
import org.bson.Document;
import org.bson.types.ObjectId;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Service
public class RecordWorkflowService {
    private final JdbcClient jdbc;private final MongoTemplate mongo;private final DatasetService datasets;private final AuditService audit;private final JsonSupport json;private final RdpProperties properties;private final SecondaryCredentialService secondaryCredentials;
    public RecordWorkflowService(JdbcClient jdbc,MongoTemplate mongo,DatasetService datasets,AuditService audit,JsonSupport json,RdpProperties properties,SecondaryCredentialService secondaryCredentials){this.jdbc=jdbc;this.mongo=mongo;this.datasets=datasets;this.audit=audit;this.json=json;this.properties=properties;this.secondaryCredentials=secondaryCredentials;}

    @Transactional
    public Map<String,Object> submit(long datasetId,String recordId,int version,String reason){Map<String,Object> dataset=datasets.get(datasetId);datasets.requireWriteAccess(dataset);Workflow workflow=lock(datasetId,recordId);UserPrincipal user=CurrentUser.require();if(!user.admin()&&workflow.ownerId()!=user.id())throw BusinessException.forbidden("仅记录创建者或管理员可提交审核");if(workflow.recordVersion()!=version)throw new BusinessException(409,"记录版本已变化，请刷新后重试");if("REJECTED".equals(workflow.status()))throw BusinessException.badRequest("驳回记录必须先受控更正并生成新版本，再重新提交");if(!"DRAFT".equals(workflow.status()))throw BusinessException.badRequest("当前状态不能提交审核");jdbc.sql("UPDATE dataset_record_workflow SET status='PENDING_REVIEW',submitted_by=:user,submitted_time=now(),reviewed_by=NULL,reviewed_time=NULL,review_comment=:reason,updated_time=now() WHERE dataset_id=:dataset AND record_id=:record")
                .param("user",user.id()).param("reason",reason).param("dataset",datasetId).param("record",recordId).update();projectAfterCommit(datasetId,recordId,"PENDING_REVIEW");audit.record("SUBMIT_REVIEW","DATASET","提交数据记录审核",Map.of("datasetId",datasetId,"recordId",recordId,"version",version,"reason",reason,"beforeStatus",workflow.status(),"afterStatus","PENDING_REVIEW"));return state(datasetId,recordId);}

    @Transactional
    public Map<String,Object> review(long datasetId,String recordId,int version,boolean approved,String reason,String secondaryPassword,String clientIp){datasets.get(datasetId);if(!datasets.canAudit(datasetId))throw BusinessException.forbidden("共享仅授予读取权限，不能审核数据");Workflow workflow=lock(datasetId,recordId);UserPrincipal user=CurrentUser.require();if(workflow.ownerId()==user.id())throw BusinessException.forbidden("为确保职责分离，记录创建者不能审核自己的记录");if(workflow.recordVersion()!=version)throw new BusinessException(409,"记录版本已变化，请刷新后重试");if(!"PENDING_REVIEW".equals(workflow.status()))throw BusinessException.badRequest("记录不在待审核状态");verifySecondaryPassword(user,secondaryPassword);String status=approved?"APPROVED":"REJECTED",meaning=approved?"REVIEW_APPROVE":"REVIEW_REJECT";jdbc.sql("UPDATE dataset_record_workflow SET status=:status,reviewed_by=:user,reviewed_time=now(),review_comment=:reason,updated_time=now() WHERE dataset_id=:dataset AND record_id=:record")
                .param("status",status).param("user",user.id()).param("reason",reason).param("dataset",datasetId).param("record",recordId).update();projectAfterCommit(datasetId,recordId,status);sign(datasetId,recordId,version,meaning,reason,user,clientIp);audit.record("REVIEW","DATASET","审核数据记录",Map.of("datasetId",datasetId,"recordId",recordId,"version",version,"result",status,"reason",reason,"clientIp",clientIp,"beforeStatus",workflow.status(),"afterStatus",status));return state(datasetId,recordId);}

    @Transactional
    public Map<String,Object> publish(long datasetId,String recordId,int version,String reason,String secondaryPassword,String clientIp){datasets.get(datasetId);if(!datasets.canAudit(datasetId))throw BusinessException.forbidden("共享仅授予读取权限，不能发布数据");Workflow workflow=lock(datasetId,recordId);UserPrincipal user=CurrentUser.require();if(workflow.recordVersion()!=version)throw new BusinessException(409,"记录版本已变化，请刷新后重试");if(!"APPROVED".equals(workflow.status()))throw BusinessException.badRequest("只有审核通过的记录可发布");verifySecondaryPassword(user,secondaryPassword);jdbc.sql("UPDATE dataset_record_workflow SET status='PUBLISHED',published_by=:user,published_time=now(),updated_time=now() WHERE dataset_id=:dataset AND record_id=:record")
                .param("user",user.id()).param("dataset",datasetId).param("record",recordId).update();projectAfterCommit(datasetId,recordId,"PUBLISHED");sign(datasetId,recordId,version,"PUBLISH",reason,user,clientIp);audit.record("PUBLISH","DATASET","发布数据记录",Map.of("datasetId",datasetId,"recordId",recordId,"version",version,"reason",reason,"clientIp",clientIp,"beforeStatus",workflow.status(),"afterStatus","PUBLISHED"));return state(datasetId,recordId);}

    public Map<String,Object> state(long datasetId,String recordId){datasets.get(datasetId);Workflow workflow=ensure(datasetId,recordId);requireVisible(workflow);Map<String,Object> value=new LinkedHashMap<>();value.put("datasetId",workflow.datasetId());value.put("recordId",workflow.recordId());value.put("businessCode",workflow.businessCode());value.put("recordVersion",workflow.recordVersion());value.put("ownerId",workflow.ownerId());value.put("status",workflow.status());value.put("submittedBy",workflow.submittedBy());value.put("submittedTime",workflow.submittedTime());value.put("reviewedBy",workflow.reviewedBy());value.put("reviewedTime",workflow.reviewedTime());value.put("reviewComment",workflow.reviewComment());value.put("publishedBy",workflow.publishedBy());value.put("publishedTime",workflow.publishedTime());value.put("signatures",signatureRows(datasetId,recordId));return value;}
    public List<Map<String,Object>> signatures(long datasetId,String recordId){datasets.get(datasetId);Workflow workflow=ensure(datasetId,recordId);requireVisible(workflow);return signatureRows(datasetId,recordId);}
    private List<Map<String,Object>> signatureRows(long datasetId,String recordId){return jdbc.sql("SELECT id,target_version,signer_id,signer_username,meaning,reason,evidence_digest,signature_key_id,signature_ip,signed_payload,signed_time FROM electronic_signature WHERE target_type='DATASET_RECORD' AND target_id=:target ORDER BY signed_time")
                .param("target",datasetId+":"+recordId).query((rs,n)->{Map<String,Object> value=new LinkedHashMap<>();value.put("id",rs.getLong("id"));value.put("targetVersion",rs.getInt("target_version"));value.put("signerId",rs.getLong("signer_id"));value.put("signerUsername",rs.getString("signer_username"));value.put("meaning",rs.getString("meaning"));value.put("reason",rs.getString("reason"));value.put("evidenceDigest",rs.getString("evidence_digest"));value.put("signatureKeyId",rs.getString("signature_key_id"));value.put("signatureIp",rs.getString("signature_ip"));Map<String,Object> signed=json.map(rs.getString("signed_payload"));value.put("recordContentDigest",signed.get("recordContentDigest"));value.put("attachmentManifestDigest",signed.get("attachmentManifestDigest"));value.put("signedTime",rs.getObject("signed_time"));return value;}).list();}

    public Map<String,Object> verifySignature(long datasetId,String recordId,long signatureId){datasets.get(datasetId);Workflow workflow=ensure(datasetId,recordId);requireVisible(workflow);Signature row=jdbc.sql("SELECT id,target_type,target_id,target_version,signer_id,signer_username,meaning,reason,signed_payload,evidence_digest,signature_key_id,signature_ip,signed_time FROM electronic_signature WHERE id=:id AND target_type='DATASET_RECORD' AND target_id=:target").param("id",signatureId).param("target",datasetId+":"+recordId).query((rs,n)->new Signature(rs.getLong("id"),rs.getString("target_type"),rs.getString("target_id"),rs.getInt("target_version"),rs.getLong("signer_id"),rs.getString("signer_username"),rs.getString("meaning"),rs.getString("reason"),rs.getString("signed_payload"),rs.getString("evidence_digest"),rs.getString("signature_key_id"),rs.getString("signature_ip"),rs.getTimestamp("signed_time").toInstant())).optional().orElseThrow(()->BusinessException.notFound("电子签名不存在"));Map<String,Object> payload;try{payload=json.map(row.signedPayload());}catch(Exception ex){payload=Map.of();}String key=signatureKey(row.keyId());boolean columnsMatch=signaturePayloadMatches(row,payload),digestMatches=key!=null&&MessageDigest.isEqual(hmac(key,row.signedPayload()).getBytes(StandardCharsets.UTF_8),row.evidenceDigest().getBytes(StandardCharsets.UTF_8)),valid=columnsMatch&&digestMatches;Map<String,Object> result=new LinkedHashMap<>();result.put("valid",valid);result.put("signatureId",row.id());result.put("signatureKeyId",row.keyId());result.put("signatureIp",row.clientIp());result.put("message",valid?"电子签名载荷、业务摘要和密钥版本校验通过":key==null?"未配置该签名使用的历史密钥":"电子签名载荷或摘要校验失败");result.put("evidenceDigest",row.evidenceDigest());result.put("signedPayload",row.signedPayload());result.put("payload",payload);audit.record("VERIFY_SIGNATURE","DATASET","验证数据记录电子签名",Map.of("datasetId",datasetId,"recordId",recordId,"signatureId",signatureId,"signatureKeyId",row.keyId(),"valid",valid));return result;}

    private Workflow lock(long datasetId,String recordId){ensure(datasetId,recordId);return jdbc.sql("SELECT * FROM dataset_record_workflow WHERE dataset_id=:dataset AND record_id=:record FOR UPDATE").param("dataset",datasetId).param("record",recordId).query(Workflow.class).single();}
    private Workflow ensure(long datasetId,String recordId){validateId(recordId);Workflow existing=jdbc.sql("SELECT * FROM dataset_record_workflow WHERE dataset_id=:dataset AND record_id=:record").param("dataset",datasetId).param("record",recordId).query(Workflow.class).optional().orElse(null);if(existing!=null)return existing;Document document=mongo.findOne(Query.query(Criteria.where("_id").is(new ObjectId(recordId)).and("deleted").ne(true)),Document.class,"dataset_data_"+datasetId);if(document==null)throw BusinessException.notFound("记录不存在");Number owner=document.get("createdBy",Number.class);jdbc.sql("""
                INSERT INTO dataset_record_workflow(dataset_id,record_id,business_code,record_version,owner_id,status,search_data,
                                                    record_created_time,record_updated_time,search_projection_ready)
                VALUES (:dataset,:record,:businessCode,:version,:owner,'DRAFT',CAST(:data AS jsonb),:created,:updated,TRUE)
                ON CONFLICT DO NOTHING
                """)
                .param("dataset",datasetId).param("record",recordId).param("version",document.getInteger("version",1))
                .param("businessCode",datasets.legacyBusinessCode(datasetId,document))
                .param("owner",owner.longValue()).param("data",json.write(document.get("data")))
                .param("created",timestamp(document.get("createdTime"))).param("updated",timestamp(document.get("updatedTime")!=null?document.get("updatedTime"):document.get("createdTime"))).update();return jdbc.sql("SELECT * FROM dataset_record_workflow WHERE dataset_id=:dataset AND record_id=:record").param("dataset",datasetId).param("record",recordId).query(Workflow.class).single();}
    private void verifySecondaryPassword(UserPrincipal user,String secondaryPassword){String hash=jdbc.sql("SELECT coalesce(secondary_password,'') FROM sys_user WHERE id=:id AND status=1 AND deleted=0").param("id",user.id()).query(String.class).optional().orElseThrow(()->BusinessException.unauthorized("签名账号不可用"));secondaryCredentials.verify(user,secondaryPassword,hash,"SIGNATURE");}
    private void sign(long datasetId,String recordId,int version,String meaning,String reason,UserPrincipal user,String clientIp){Instant time=Instant.now().truncatedTo(ChronoUnit.MICROS);Document record=mongo.findOne(Query.query(Criteria.where("_id").is(new ObjectId(recordId)).and("deleted").ne(true).and("archived").ne(true)),Document.class,"dataset_data_"+datasetId);if(record==null)throw BusinessException.notFound("待签名记录不存在");List<Map<String,Object>> attachments=jdbc.sql("SELECT id,original_name,content_type,size_bytes,sha256 FROM file_asset WHERE business_type='DATASET_RECORD' AND business_ref=:ref AND status='AVAILABLE' ORDER BY id").param("ref",datasetId+":"+recordId).query((rs,n)->Map.<String,Object>of("id",rs.getLong("id"),"name",rs.getString("original_name"),"contentType",rs.getString("content_type"),"sizeBytes",rs.getLong("size_bytes"),"sha256",rs.getString("sha256"))).list();String keyId=properties.security().auditKeyId();Map<String,Object> payload=new LinkedHashMap<>();payload.put("targetType","DATASET_RECORD");payload.put("targetId",datasetId+":"+recordId);payload.put("targetVersion",version);payload.put("recordContentDigest",sha256(json.canonical(record.get("data"))));payload.put("attachmentManifestDigest",sha256(json.canonical(attachments)));payload.put("attachmentCount",attachments.size());payload.put("signerId",user.id());payload.put("signerUsername",user.username());payload.put("meaning",meaning);payload.put("reason",reason);payload.put("signedTime",time.toString());payload.put("signatureIp",clientIp);payload.put("authentication","SECONDARY_PASSWORD");payload.put("signatureKeyId",keyId);String signed=json.canonical(payload),digest=hmac(properties.security().auditSecret(),signed);jdbc.sql("INSERT INTO electronic_signature(target_type,target_id,target_version,signer_id,signer_username,meaning,reason,signed_payload,evidence_digest,signature_key_id,signature_ip,signed_time) VALUES ('DATASET_RECORD',:target,:version,:signer,:username,:meaning,:reason,:payload,:digest,:keyId,:clientIp,:time)")
                .param("target",datasetId+":"+recordId).param("version",version).param("signer",user.id()).param("username",user.username()).param("meaning",meaning).param("reason",reason).param("payload",signed).param("digest",digest).param("keyId",keyId).param("clientIp",clientIp).param("time",java.sql.Timestamp.from(time)).update();}
    private void projectAfterCommit(long datasetId,String recordId,String status){if(!TransactionSynchronizationManager.isSynchronizationActive()){setProjection(datasetId,recordId,status);return;}TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){try{setProjection(datasetId,recordId,status);}catch(Exception ignored){/* 定时投影修复任务会按PG权威状态重试。 */}}});}
    private void setProjection(long datasetId,String recordId,String status){mongo.updateFirst(Query.query(Criteria.where("_id").is(new ObjectId(recordId)).and("deleted").ne(true)),new org.springframework.data.mongodb.core.query.Update().set("workflowStatus",status),"dataset_data_"+datasetId);}
    private java.sql.Timestamp timestamp(Object value){if(value instanceof Instant instant)return java.sql.Timestamp.from(instant);if(value instanceof java.util.Date date)return new java.sql.Timestamp(date.getTime());return java.sql.Timestamp.from(Instant.now());}
    private void requireVisible(Workflow workflow){UserPrincipal user=CurrentUser.require();if(!datasets.canAudit(workflow.datasetId())&&workflow.ownerId()!=user.id()&&!"PUBLISHED".equals(workflow.status()))throw BusinessException.notFound("记录不存在");}
    private boolean signaturePayloadMatches(Signature row,Map<String,Object> payload){Object version=payload.get("targetVersion"),signer=payload.get("signerId");boolean legacy="legacy-unversioned".equals(row.keyId())&&!payload.containsKey("signatureKeyId");return row.targetType().equals(payload.get("targetType"))&&row.targetId().equals(payload.get("targetId"))&&version instanceof Number v&&v.intValue()==row.targetVersion()&&signer instanceof Number s&&s.longValue()==row.signerId()&&row.signerUsername().equals(payload.get("signerUsername"))&&row.meaning().equals(payload.get("meaning"))&&row.reason().equals(payload.get("reason"))&&row.signedTime().toString().equals(payload.get("signedTime"))&&(legacy||row.keyId().equals(payload.get("signatureKeyId")))&&(legacy||row.clientIp().equals(payload.get("signatureIp")));}
    private String signatureKey(String keyId){if(properties.security().auditKeyId().equals(keyId))return properties.security().auditSecret();String previous=properties.security().auditPreviousKeys();if(previous==null||previous.isBlank())return null;for(String entry:previous.split(";")){int split=entry.indexOf('=');if(split>0&&entry.substring(0,split).equals(keyId))return entry.substring(split+1);}return null;}
    private String hmac(String secret,String value){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception ex){throw new IllegalStateException(ex);}}
    private String sha256(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception ex){throw new IllegalStateException(ex);}}
    private void validateId(String value){try{new ObjectId(value);}catch(Exception ex){throw BusinessException.badRequest("记录ID格式不正确");}}
    private record Workflow(long datasetId,String recordId,String businessCode,int recordVersion,long ownerId,String status,Long submittedBy,Instant submittedTime,Long reviewedBy,Instant reviewedTime,String reviewComment,Long publishedBy,Instant publishedTime,Instant updatedTime){}
    private record Signature(long id,String targetType,String targetId,int targetVersion,long signerId,String signerUsername,String meaning,String reason,String signedPayload,String evidenceDigest,String keyId,String clientIp,Instant signedTime){}
}
